package com.studentgig.controller;
import com.studentgig.ai.AIResumeService; import com.studentgig.model.User; import com.studentgig.repository.UserRepository; import jakarta.servlet.http.HttpSession; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/resume") public class ResumeController {final UserRepository users;final AIResumeService ai;ResumeController(UserRepository u,AIResumeService a){users=u;ai=a;}@PostMapping("/generate") public Object generate(@RequestBody Map<String,String> p,HttpSession s){Object id=s.getAttribute("userId");if(id==null)return Map.of("error","Please login");User u=users.findById((Long)id).orElseThrow();return Map.of("html",ai.generate(u,p.getOrDefault("targetRole","Software Developer"),p.getOrDefault("jobDescription","")));}}
